<?php
require_once __DIR__.'/config.php'; require_login(); verify_csrf();
$id=(int)$_SESSION['usuario_id']; $error='';
$conexion->query("INSERT IGNORE INTO perfil_usuario(id_usuario) SELECT id_usuario FROM usuarios");
if($_SERVER['REQUEST_METHOD']==='POST'){
 $nombre=trim($_POST['nombre']??'');$apellido=trim($_POST['apellido']??'');$bio=trim($_POST['biografia']??'');
 if($nombre===''||$apellido==='') $error='El nombre y el apellido son obligatorios.';
 elseif(mb_strlen($bio)>500) $error='La biografía no puede superar 500 caracteres.';
 else {
  $get=$conexion->prepare('SELECT foto_perfil,banner_perfil FROM perfil_usuario WHERE id_usuario=?');$get->bind_param('i',$id);$get->execute();$old=$get->get_result()->fetch_assoc()?:[];$foto=$old['foto_perfil']??null;$banner=$old['banner_perfil']??null;
  foreach(['foto_perfil'=>'foto','banner_perfil'=>'banner'] as $field=>$key){ if(!empty($_FILES[$field]['name'])){ $file=$_FILES[$field]; if($file['error']!==UPLOAD_ERR_OK){$error='No se pudo subir una imagen. Revisa su tamaño.';break;} if($file['size']>3*1024*1024){$error='Cada imagen debe pesar como máximo 3 MB.';break;} $info=@getimagesize($file['tmp_name']); if(!$info || !in_array($info['mime'],['image/jpeg','image/png','image/webp'],true)){$error='Usa imágenes JPG, PNG o WEBP.';break;} $ext=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp'][$info['mime']];$dir=__DIR__.'/uploads/perfiles';if(!is_dir($dir)&&!mkdir($dir,0755,true)){$error='No se pudo crear la carpeta de imágenes.';break;} $filename=$key.'_'.$id.'_'.bin2hex(random_bytes(6)).'.'.$ext;if(!move_uploaded_file($file['tmp_name'],$dir.'/'.$filename)){$error='No se pudo guardar la imagen.';break;} if($key==='foto')$foto='uploads/perfiles/'.$filename;else $banner='uploads/perfiles/'.$filename; }}
  if(!$error){$q=$conexion->prepare('UPDATE usuarios SET nombre=?,apellido=? WHERE id_usuario=?');$q->bind_param('ssi',$nombre,$apellido,$id);$q->execute();$q=$conexion->prepare('INSERT INTO perfil_usuario(id_usuario,biografia,foto_perfil,banner_perfil) VALUES(?,?,?,?) ON DUPLICATE KEY UPDATE biografia=VALUES(biografia),foto_perfil=VALUES(foto_perfil),banner_perfil=VALUES(banner_perfil)');$q->bind_param('isss',$id,$bio,$foto,$banner);$q->execute();$_SESSION['nombre']=$nombre;$_SESSION['apellido']=$apellido;flash('Tu perfil se actualizó correctamente.');header('Location: perfil.php');exit;}
 }
}
$q=$conexion->prepare('SELECT u.nombre,u.apellido,u.correo,u.rol,p.biografia,p.foto_perfil,p.banner_perfil FROM usuarios u LEFT JOIN perfil_usuario p ON p.id_usuario=u.id_usuario WHERE u.id_usuario=?');$q->bind_param('i',$id);$q->execute();$user=$q->get_result()->fetch_assoc();
?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Mi perfil | MokaSports</title><link rel="stylesheet" href="assets/style.css"></head><body class="app-body"><main class="main-content profile-page"><header class="topbar profile-topbar"><div><span class="eyebrow">TU ESPACIO PERSONAL</span><h1>Editar perfil</h1><p class="muted">Dale tu estilo a MokaSports y mantén tus datos al día.</p></div><div class="top-actions"><a class="btn btn-secondary" href="<?=($_SESSION['rol']==='Administrador'?'admin.php':'estudiante.php')?>">⌂ Ir a inicio</a></div></header><?php show_flash();if($error):?><div class="alert error"><?=e($error)?></div><?php endif;?><section class="profile-card"><div class="profile-cover" style="<?=!empty($user['banner_perfil'])?'background-image:url(\''.e($user['banner_perfil']).'\')':''?>"></div><div class="profile-head"><img class="profile-avatar" src="<?=e($user['foto_perfil']?:'assets/avatar-default.svg')?>" alt="Foto de perfil"><div><h2><?=e($user['nombre'].' '.$user['apellido'])?></h2><p class="muted profile-meta"><?=e($user['correo'])?></p><span class="profile-role"><?=e($user['rol'])?></span></div></div><div class="profile-editor-intro"><span class="profile-editor-icon">✦</span><div><h2>Información personal</h2><p class="muted">Los campos con nombre y apellido son obligatorios.</p></div></div><form method="post" enctype="multipart/form-data" class="editor-card profile-editor"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><div class="form-grid"><label>Nombre<input name="nombre" maxlength="100" required value="<?=e($user['nombre'])?>"></label><label>Apellido<input name="apellido" maxlength="100" required value="<?=e($user['apellido'])?>"></label><label class="full-field">Biografía <span class="field-hint">Máximo 500 caracteres</span><textarea id="biografia" name="biografia" maxlength="500" rows="4" placeholder="Cuéntale algo a tu comunidad deportiva..."><?=e($user['biografia']??'')?></textarea><small class="char-count"><span id="bioCount"><?=mb_strlen($user['biografia']??'')?></span>/500 caracteres</small></label><label class="upload-field"><span>Foto de perfil</span><small>JPG, PNG o WEBP · Máx. 3 MB</small><input id="fotoInput" type="file" name="foto_perfil" accept="image/jpeg,image/png,image/webp"><div class="image-position"><label for="fotoX">Acomodar horizontal</label><input id="fotoX" type="range" min="0" max="100" value="50"><label for="fotoY">Acomodar vertical</label><input id="fotoY" type="range" min="0" max="100" value="50"></div></label><label class="upload-field"><span>Banner de perfil</span><small>JPG, PNG o WEBP · Máx. 3 MB</small><input id="bannerInput" type="file" name="banner_perfil" accept="image/jpeg,image/png,image/webp"><div class="image-position"><label for="bannerX">Acomodar horizontal</label><input id="bannerX" type="range" min="0" max="100" value="50"><label for="bannerY">Acomodar vertical</label><input id="bannerY" type="range" min="0" max="100" value="50"></div></label></div><div class="profile-form-actions"><p class="muted">✦ Tus cambios se guardarán en tu cuenta.</p><button class="btn btn-primary" type="submit">Guardar cambios <span>✓</span></button></div></form></section></main><script>
const avatar=document.querySelector('.profile-avatar'), cover=document.querySelector('.profile-cover');
function previewFile(input, target, isCover){input?.addEventListener('change',()=>{const file=input.files?.[0];if(!file)return;if(!file.type.startsWith('image/'))return;const url=URL.createObjectURL(file);if(isCover)target.style.backgroundImage=`url("${url}")`;else target.src=url;});}
previewFile(document.getElementById('fotoInput'),avatar,false);previewFile(document.getElementById('bannerInput'),cover,true);
[['fotoX','fotoY',avatar],['bannerX','bannerY',cover]].forEach(([x,y,el])=>{const update=()=>{const px=document.getElementById(x).value,py=document.getElementById(y).value;if(el===cover)el.style.backgroundPosition=`${px}% ${py}%`;else el.style.objectPosition=`${px}% ${py}%`;};document.getElementById(x).addEventListener('input',update);document.getElementById(y).addEventListener('input',update);});
const bio=document.getElementById('biografia'), count=document.getElementById('bioCount');bio?.addEventListener('input',()=>count.textContent=bio.value.length);
</script><script src="assets/app.js"></script></body></html>